		private void DispatchInMainWindow(Action action)
		{
			// Helper to ensure UI and switcher commands occur on MainWindow thread
			if (!Dispatcher.CheckAccess())
				Dispatcher.Invoke(action);
			else
				action.Invoke();
		}

		private static void EnableChildControls(DependencyObject parent, bool enable)
		{
			// Recursively find child elements and enable or disable
			for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
			{
				var child = VisualTreeHelper.GetChild(parent, i);

				if (child is UIElement)
					((UIElement)child).IsEnabled = enable;

				EnableChildControls(child, enable);
			}
		}

		public MainWindow()
		{
			InitializeComponent();
		}

		// Record has started, start monitoring task
		private async void StartRecordMonitoring()
		{
			if (switcherRecordAVDevice != null)
			{
				try
				{
					buttonStartStopRecording.Content = "Stop Recording";
					EnableChildControls(groupBoxRecordSettings, false);
					buttonConnect.IsEnabled = false;
					buttonSwitchDisk.IsEnabled = comboBoxDisk2.SelectedIndex >= 0;

					recordingStoppingCancel = new CancellationTokenSource();
					switcherDisconnectedCancel = new CancellationTokenSource();
					windowClosingCancel = new CancellationTokenSource();

					await switcherRecordAVDevice.TaskRecord(recordingStoppingCancel.Token, switcherDisconnectedCancel.Token, windowClosingCancel.Token);
				}
				catch (TaskCanceledException)
				{
				}
				finally
				{
					recordingStoppingCancel.Dispose();
					recordingStoppingCancel = null;

					switcherDisconnectedCancel.Dispose();
					switcherDisconnectedCancel = null;

					windowClosingCancel.Dispose();
					windowClosingCancel = null;

					buttonStartStopRecording.Content = "Start Recording";
					EnableChildControls(groupBoxRecordSettings, true);
					buttonConnect.IsEnabled = true;
					buttonSwitchDisk.IsEnabled = false;
				}
			}
		}

		private void RefreshDisk1Controls()
		{
			// Update binding
			comboBoxDisk1.DataContext = this;

			var disk1WorkingSet = switcherRecordAVDevice.Disk1WorkingSet;
			if (disk1WorkingSet < comboBoxDisk1.Items.Count)
			{
				comboBoxDisk1.SelectedValue = disk1WorkingSet;
				textBoxDisk1Status.Text = GetDiskStatusString(switcherRecordAVDevice.GetDiskStatus(disk1WorkingSet));
				textBoxDisk1Duration.Text = RecordingTimeToString(switcherRecordAVDevice.GetDiskRecordingTimeAvailable(disk1WorkingSet));
			}
			else
			{
				comboBoxDisk1.SelectedIndex = -1;   // No selection
				textBoxDisk1Status.Text = String.Empty;
				textBoxDisk1Duration.Text = String.Empty;
			}
		}

		private void RefreshDisk2Controls()
		{
			// Update binding
			comboBoxDisk2.DataContext = this;

			var disk2WorkingSet = switcherRecordAVDevice.Disk2WorkingSet;
			if (disk2WorkingSet < comboBoxDisk2.Items.Count)
			{
				comboBoxDisk2.SelectedValue = disk2WorkingSet;
