			}
		}

		private void SetIPAddressTextBoxEnabled(bool enabled)
		{
			textBoxIPAddr1.IsEnabled = enabled;
			textBoxIPAddr2.IsEnabled = enabled;
			textBoxIPAddr3.IsEnabled = enabled;
			textBoxIPAddr4.IsEnabled = enabled;
		}

		private bool HandleIPAddressEntry(string ipAddressString, bool moveFocusOnPeriod)
		{
			bool enteredPeriod = moveFocusOnPeriod && ipAddressString.EndsWith(".");
			bool ipAddressIsValid = IsIpAddressByteValid(enteredPeriod ? ipAddressString.TrimEnd('.') : ipAddressString);

			if (enteredPeriod && ipAddressIsValid)
			{
				FocusNavigationDirection focusDirection = FocusNavigationDirection.Next;

				// MoveFocus takes a TraveralReqest as its argument.
				TraversalRequest request = new TraversalRequest(focusDirection);

				// Gets the element with keyboard focus.
				UIElement elementWithFocus = Keyboard.FocusedElement as UIElement;

				// Change keyboard focus.
				return elementWithFocus?.MoveFocus(request) ?? false;
			}

			return !ipAddressIsValid;
		}

		private bool HandleConnectEvent()
		{
			// Validate IP Address fields
			if (!IsIpAddressByteValid(textBoxIPAddr1.Text) ||
				!IsIpAddressByteValid(textBoxIPAddr2.Text) ||
				!IsIpAddressByteValid(textBoxIPAddr3.Text) ||
				!IsIpAddressByteValid(textBoxIPAddr4.Text))
				return true;

			string ipAddress = textBoxIPAddr1.Text + '.' + textBoxIPAddr2.Text + '.' + textBoxIPAddr3.Text + '.' + textBoxIPAddr4.Text;

			try
			{
				switcherRecordAVDevice = new SwitcherRecordAVDevice(ipAddress, switcherRecordAVMonitor, switcherRecordDiskMonitor, switcherMonitor);
			}
			catch (SwitcherConnectException e)
			{
				MessageBox.Show(e.Message, "Switcher Connection Error");
				return true;
			}
			catch (SwitcherRecordInvalidException e)
			{
				MessageBox.Show(e.Message, "Switcher Record Invalid Error");
				return true;
			}

			// Update UI with values from connected switcher
			textBoxProductName.Text = switcherRecordAVDevice.ProductName;
			textBoxFileBasename.Text = switcherRecordAVDevice.RecordingFilename;
			checkBoxRecordInAllCameras.IsChecked = switcherRecordAVDevice.RecordInAllCameras;
			checkBoxISORecording.Visibility = switcherRecordAVDevice.SupportsISORecording ? Visibility.Visible : Visibility.Collapsed;
			checkBoxISORecording.IsChecked = switcherRecordAVDevice.SupportsISORecording ? switcherRecordAVDevice.RecordAllISOInputs : false;

			UpdateRecordStatus(switcherRecordAVDevice.RecordStatus);
			statusBarItemTimecode.Text = switcherRecordAVDevice.TimecodeHMSString;
			statusBarRecordingTimeAvailable.Text = RecordingTimeToString(switcherRecordAVDevice.TotalRecordingTimeAvailable);

			var diskIdKeyValuePairs = switcherRecordAVDevice.AvailableDiskIds.Select(id => new KeyValuePair<uint, string>(id, switcherRecordAVDevice.GetDiskVolumeName(id)));
			RecordDiskIdCollection = new ObservableCollection<KeyValuePair<uint, string>>(diskIdKeyValuePairs);
			RefreshDisk1Controls();
			RefreshDisk2Controls();

			SetIPAddressTextBoxEnabled(false);
			buttonConnect.Content = "Disconnect";

			EnableChildControls(groupBoxRecordSettings, true);
			buttonStartStopRecording.IsEnabled = RecordDiskIdCollection.Count >= 0;

			if (switcherRecordAVDevice.IsRecording)
			{
				// Switcher is already recording, start record task
				StartRecordMonitoring();
			}

			return false;
		}

		private void HandleDisconnectEvent()
		{
			switcherRecordAVDevice?.Disable();
			switcherRecordAVDevice = null;

			SetIPAddressTextBoxEnabled(true);
			EnableChildControls(groupBoxRecordSettings, false);
			buttonStartStopRecording.IsEnabled = false;

			textBoxProductName.Clear();
			textBoxFileBasename.Clear();
			checkBoxRecordInAllCameras.IsChecked = false;
			checkBoxISORecording.IsChecked = false;

			comboBoxDisk1.SelectedIndex = -1;
			textBoxDisk1Status.Clear();
			textBoxDisk1Duration.Clear();
			comboBoxDisk2.SelectedIndex = -1;
			textBoxDisk2Status.Clear();
			textBoxDisk2Duration.Clear();

			buttonConnect.Content = "Connect";

			statusBarRecordStatus.Text = "Not connected";
			statusBarItemTimecode.Text = "00:00:00";
			statusBarRecordingTimeAvailable.Text = RecordingTimeToString(0);

		}

		private static bool IsIpAddressByteValid(string str)
		{
			return int.TryParse(str, out int i) && i >= 0 && i <= 255;
		}


		#region switcher_monitor_events
		private void SwitcherMonitor_SwitcherDisconnected(object sender, EventArgs e)
		{
			switcherDisconnectedCancel?.Cancel();
			DispatchInMainWindow(() => { HandleDisconnectEvent(); });
		}
