		private void SwitcherRecordAVMonitor_TotalRecordingTimeAvailableChanged(object sender, EventArgs e)
		{
			DispatchInMainWindow(() => { statusBarRecordingTimeAvailable.Text = RecordingTimeToString(switcherRecordAVDevice.TotalRecordingTimeAvailable); });
		}

		private void SwitcherRecordAVMonitor_WorkingSetChanged(object sender, WorkingSetEventArgs e)
		{
			DispatchInMainWindow(() =>
			{
				switch (e.WorkingSetIndex)
				{
					case 0:
						SetDisk1Selection(e.DiskId);
						break;

					case 1:
						SetDisk2Selection(e.DiskId);
						break;
				}
			});
		}

		private void SwitcherRecordAVMonitor_DiskAvailable(object sender, DiskAvailabilityEventArgs e)
		{
			DispatchInMainWindow(() =>
			{
				switcherRecordAVDevice.DiskWithIDAvailable(e.DiskID);

				RecordDiskIdCollection.Add(new KeyValuePair<uint, string>(e.DiskID, switcherRecordAVDevice.GetDiskVolumeName(e.DiskID)));
				RefreshDisk1Controls();
				RefreshDisk2Controls();

				buttonStartStopRecording.IsEnabled = RecordDiskIdCollection.Count > 0;
			});
		}

		private void SwitcherRecordAVMonitor_DiskRemoved(object sender, DiskAvailabilityEventArgs e)
		{
			DispatchInMainWindow(() =>
			{
				switcherRecordAVDevice.DiskWithIDRemoved(e.DiskID);

				RecordDiskIdCollection.Remove(RecordDiskIdCollection.First(id => id.Key.Equals(e.DiskID)));
				RefreshDisk1Controls();
				RefreshDisk2Controls();

				buttonStartStopRecording.IsEnabled = RecordDiskIdCollection.Count > 0;
			});
		}

		private void SwitcherRecordAVMonitor_StatusUpdated(object sender, StatusUpdatedEventArgs e)
		{
			if (e.StateType == _BMDSwitcherRecordAVState.bmdSwitcherRecordAVStateRecording)
			{
				// Recording has started, start monitoring task
				DispatchInMainWindow(() => { StartRecordMonitoring(); });
			}
			else if (e.StateType == _BMDSwitcherRecordAVState.bmdSwitcherRecordAVStateStopping)
			{
				// Recording is stopping, stop monitoring task
				recordingStoppingCancel?.Cancel();
			}

			UpdateRecordStatus(e.StateType);
		}

		private void UpdateRecordStatus(_BMDSwitcherRecordAVState state)
		{
			DispatchInMainWindow(() =>
			{
				string statusString;
				try
				{
					statusString = RecordStatusString[state];
				}
				catch (KeyNotFoundException)
				{
					statusString = "Invalid";
				}

				statusBarRecordStatus.Text = statusString;
			});
		}

		private string GetDiskStatusString(_BMDSwitcherRecordDiskStatus diskStatus)
		{
			try
			{
				return RecordDiskStatusString[diskStatus];
			}
			catch (KeyNotFoundException)
			{
				return "Invalid";
			}
		}

		private void SetDisk1Selection(uint diskId)
		{
			if (diskId == InvalidDiskId)
			{
				comboBoxDisk1.IsEnabled = false;
				comboBoxDisk1.SelectedIndex = -1;
				buttonStartStopRecording.IsEnabled = false;
				textBoxDisk1Status.Text = "";
				textBoxDisk1Duration.Text = "";
			}
			else
			{
				comboBoxDisk1.IsEnabled = true;
				comboBoxDisk1.SelectedValue = diskId;
				buttonStartStopRecording.IsEnabled = true;
			}
		}

		private void SetDisk2Selection(uint diskId)
		{
			if (diskId == InvalidDiskId)
			{
				comboBoxDisk2.IsEnabled = false;
				comboBoxDisk2.SelectedIndex = -1;
				buttonSwitchDisk.IsEnabled = false;
				textBoxDisk2Status.Text = "";
				textBoxDisk2Duration.Text = "";
			}
			else
			{
				comboBoxDisk2.IsEnabled = true;
				comboBoxDisk2.SelectedValue = diskId;
			}
		}

		private string RecordingTimeToString(uint recordingTime)
		{
			if (recordingTime == InvalidRecordingTime)
				recordingTime = 0;

			var recordingTimeMinutes = recordingTime / 60;
			return String.Format("{0:D} hr {1:D2} min", recordingTimeMinutes / 60, recordingTimeMinutes % 60);
		}

		private void SwitcherRecordAVMonitor_ErrorOccurred(object sender, RecordingErrorEventArgs e)
		{
			DispatchInMainWindow(() => { MessageBox.Show(e.Error, "Error"); });
		}
