		#region switcher_record_disk_monitor_events
		private void SwitcherRecordDiskMonitor_VolumeNameChanged(object sender, RecordDiskEventArgs e)
		{
			DispatchInMainWindow(() =>
			{
				var idx = RecordDiskIdCollection.ToList<KeyValuePair<uint, string>>().FindIndex(item => item.Key.Equals(e.DiskID));
				if (idx == -1)
					return;

				RecordDiskIdCollection[idx] = new KeyValuePair<uint, string>(e.DiskID, switcherRecordAVDevice.GetDiskVolumeName(e.DiskID));
				comboBoxDisk1.GetBindingExpression(ComboBox.ItemsSourceProperty).UpdateTarget();
				comboBoxDisk2.GetBindingExpression(ComboBox.ItemsSourceProperty).UpdateTarget();
			});
		}

		private void SwitcherRecordDiskMonitor_RecordingTimeAvailableChanged(object sender, RecordDiskEventArgs e)
		{
			DispatchInMainWindow(() =>
			{
				if (comboBoxDisk1.SelectedValue?.Equals(e.DiskID) ?? false)
				{
					textBoxDisk1Duration.Text = RecordingTimeToString(switcherRecordAVDevice.GetDiskRecordingTimeAvailable(e.DiskID));
				}
				else if (comboBoxDisk2.SelectedValue?.Equals(e.DiskID) ?? false)
				{
					textBoxDisk2Duration.Text = RecordingTimeToString(switcherRecordAVDevice.GetDiskRecordingTimeAvailable(e.DiskID));
				}
			});
		}

		private void SwitcherRecordDiskMonitor_StatusChanged(object sender, RecordDiskEventArgs e)
		{
			DispatchInMainWindow(() =>
			{
				_BMDSwitcherRecordDiskStatus diskStatus = switcherRecordAVDevice.GetDiskStatus(e.DiskID);

				if (comboBoxDisk1.SelectedValue?.Equals(e.DiskID) ?? false)
				{
					textBoxDisk1Status.Text = GetDiskStatusString(diskStatus);
				}
				else if (comboBoxDisk2.SelectedValue?.Equals(e.DiskID) ?? false)
				{
					textBoxDisk2Status.Text = GetDiskStatusString(diskStatus);
				}
			});
		}
		#endregion

		#region uievents
		private void Window_Loaded(object sender, RoutedEventArgs e)
		{
			switcherMonitor = new SwitcherMonitor();
			switcherMonitor.SwitcherDisconnected += SwitcherMonitor_SwitcherDisconnected;

			switcherRecordAVMonitor = new SwitcherRecordAVMonitor();
			switcherRecordAVMonitor.RecordAllISOInputsChanged += SwitcherRecordAVMonitor_RecordAllISOInputsChanged;
			switcherRecordAVMonitor.RecordInAllCamerasChanged += SwitcherRecordAVMonitor_RecordInAllCamerasChanged;
			switcherRecordAVMonitor.TimecodeChanged += SwitcherRecordAVMonitor_TimecodeChanged;
			switcherRecordAVMonitor.FilenameChanged += SwitcherRecordAVMonitor_FilenameChanged;
			switcherRecordAVMonitor.TotalRecordingTimeAvailableChanged += SwitcherRecordAVMonitor_TotalRecordingTimeAvailableChanged;
			switcherRecordAVMonitor.WorkingSetChanged += SwitcherRecordAVMonitor_WorkingSetChanged;
			switcherRecordAVMonitor.DiskAvailable += SwitcherRecordAVMonitor_DiskAvailable;
			switcherRecordAVMonitor.DiskRemoved += SwitcherRecordAVMonitor_DiskRemoved;
			switcherRecordAVMonitor.StatusUpdated += SwitcherRecordAVMonitor_StatusUpdated;
			switcherRecordAVMonitor.ErrorOccurred += SwitcherRecordAVMonitor_ErrorOccurred;

			switcherRecordDiskMonitor = new SwitcherRecordDiskMonitor();
			switcherRecordDiskMonitor.VolumeNameChanged += SwitcherRecordDiskMonitor_VolumeNameChanged;
			switcherRecordDiskMonitor.RecordingTimeAvailableChanged += SwitcherRecordDiskMonitor_RecordingTimeAvailableChanged;
			switcherRecordDiskMonitor.StatusChanged += SwitcherRecordDiskMonitor_StatusChanged;

			// Keep settings button inactive until connection
			EnableChildControls(groupBoxRecordSettings, false);
			buttonStartStopRecording.IsEnabled = false;
			buttonSwitchDisk.IsEnabled = false;
		}

		private void Window_Closing(object sender, System.ComponentModel.CancelEventArgs e)
		{
			windowClosingCancel?.Cancel();

			switcherRecordAVDevice?.Disable();
			switcherRecordAVDevice = null;

			switcherMonitor.SwitcherDisconnected -= SwitcherMonitor_SwitcherDisconnected;

			switcherRecordAVMonitor.RecordAllISOInputsChanged -= SwitcherRecordAVMonitor_RecordAllISOInputsChanged;
			switcherRecordAVMonitor.RecordInAllCamerasChanged -= SwitcherRecordAVMonitor_RecordInAllCamerasChanged;
			switcherRecordAVMonitor.TimecodeChanged -= SwitcherRecordAVMonitor_TimecodeChanged;
			switcherRecordAVMonitor.FilenameChanged -= SwitcherRecordAVMonitor_FilenameChanged;
			switcherRecordAVMonitor.TotalRecordingTimeAvailableChanged -= SwitcherRecordAVMonitor_TotalRecordingTimeAvailableChanged;
			switcherRecordAVMonitor.WorkingSetChanged -= SwitcherRecordAVMonitor_WorkingSetChanged;
			switcherRecordAVMonitor.DiskAvailable -= SwitcherRecordAVMonitor_DiskAvailable;
			switcherRecordAVMonitor.DiskRemoved -= SwitcherRecordAVMonitor_DiskRemoved;
			switcherRecordAVMonitor.StatusUpdated -= SwitcherRecordAVMonitor_StatusUpdated;
			switcherRecordAVMonitor.ErrorOccurred -= SwitcherRecordAVMonitor_ErrorOccurred;

			switcherRecordDiskMonitor.VolumeNameChanged += SwitcherRecordDiskMonitor_VolumeNameChanged;
			switcherRecordDiskMonitor.RecordingTimeAvailableChanged += SwitcherRecordDiskMonitor_RecordingTimeAvailableChanged;
			switcherRecordDiskMonitor.StatusChanged += SwitcherRecordDiskMonitor_StatusChanged;
		}

		private void TextBoxIPAddr1_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			e.Handled = HandleIPAddressEntry(((TextBox)sender).Text + e.Text, true);
		}

		private void TextBoxIPAddr2_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			e.Handled = HandleIPAddressEntry(((TextBox)sender).Text + e.Text, true);
		}

		private void TextBoxIPAddr3_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			e.Handled = HandleIPAddressEntry(((TextBox)sender).Text + e.Text, true);
		}

		private void TextBoxIPAddr4_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			if (e.Text == "\r")
			{
				e.Handled = HandleConnectEvent();
			}
			else
			{
				e.Handled = HandleIPAddressEntry(((TextBox)sender).Text + e.Text, false);
			}
		}

