		}

		private void ButtonStartStopRecording_Click(object sender, RoutedEventArgs e)
		{
			if (switcherRecordAVDevice == null)
				return;

			if (switcherRecordAVDevice.IsRecording)
				switcherRecordAVDevice.StopRecording();
			else
				switcherRecordAVDevice.StartRecording();
		}

